import{_ as a,o as s,c as i,a2 as t}from"./chunks/framework.BvlN9b-o.js";const k=JSON.parse('{"title":"Query Filters and Pagination Contracts","description":"","frontmatter":{"docLocale":"en","counterpart":"/tutorials/search-preview","contentType":"guide","prev":false,"next":false},"headers":[],"relativePath":"en/tutorials/search-preview.md","filePath":"en/tutorials/search-preview.md"}'),n={name:"en/tutorials/search-preview.md"};function r(o,e,l,h,d,p){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="query-filters-and-pagination-contracts" tabindex="-1">Query Filters and Pagination Contracts <a class="header-anchor" href="#query-filters-and-pagination-contracts" aria-label="Permalink to &quot;Query Filters and Pagination Contracts&quot;">​</a></h1><p>Goal: add bounded filters and stable pagination to your list API without exposing inaccessible resources. Start with <a href="./personal-documents">persistent business data</a> and a resource policy. Knowledge search is the reference implementation; Markdown preview is optional client functionality.</p><h2 id="from-protocol-to-query" tabindex="-1">From Protocol to Query <a class="header-anchor" href="#from-protocol-to-query" aria-label="Permalink to &quot;From Protocol to Query&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/modules/knowledge/mod.rs" target="_blank" rel="noreferrer">DocumentsQuery</a> defines <code>knowledge_base_id / q / limit / cursor</code>. Omitting the base ID selects only the personal base. <code>q</code> is trimmed, limited to 200 characters and rejects NUL; <code>limit</code> defaults to 50 with a maximum of 100. Lists return summaries and <code>next_cursor / has_more</code>, not bodies or whole-table totals.</p><p>This is the key shape of the <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/modules/knowledge/application.rs" target="_blank" rel="noreferrer">actual query</a>; complete SQL also includes current authorization, deletion state and base scope:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">AND</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ($</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">timestamptz</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> IS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NULL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> OR</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">d</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">created_at</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">d</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ($</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">timestamptz</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, $</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::uuid))</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">AND</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> d</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ILIKE $</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">6</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ORDER BY</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> d</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">created_at</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> DESC</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">d</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">id</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> DESC</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">LIMIT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span></span></code></pre></div><p>Escape LIKE <code>%</code>, <code>_</code> and backslash before binding the parameter. Thus <code>100%_</code> is a literal substring, not user-controlled wildcards. Authorization, filters and pagination belong in the database query; clients never receive private titles to filter themselves.</p><h2 id="a-cursor-is-a-position" tabindex="-1">A Cursor Is a Position <a class="header-anchor" href="#a-cursor-is-a-position" aria-label="Permalink to &quot;A Cursor Is a Position&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/modules/knowledge/pagination.rs" target="_blank" rel="noreferrer">Cursor</a> binds actor, base scope, ordering, normalized keyword digest and final position. Changing actor/scope/keyword restarts pagination. Every page reauthorizes; a cursor is neither a credential nor a cross-page database snapshot.</p><p>Fetch one extra row to determine the next page and keep lists bounded. Client Query keys include the same identity/scope/filter; the reference View retains at most ten pages. Invalid or mixed cursors return structured 400, never an unfiltered whole-table query.</p><h2 id="verify-backend-results" tabindex="-1">Verify Backend Results <a class="header-anchor" href="#verify-backend-results" aria-label="Permalink to &quot;Verify Backend Results&quot;">​</a></h2><p>Run from the repository root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/test-backend.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> knowledge</span></span></code></pre></div><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/apps/api/tests/knowledge.rs" target="_blank" rel="noreferrer">HTTP checks</a> cover literal <code>%/_</code> search, ordering, identity isolation, bound filters and denied pagination after revocation. Your list should cover two pages without duplication, rejected old cursors after filter changes, absent inaccessible titles, maximum limit and invalid input.</p><h2 id="optional-markdown-client" tabindex="-1">Optional Markdown Client <a class="header-anchor" href="#optional-markdown-client" aria-label="Permalink to &quot;Optional Markdown Client&quot;">​</a></h2><p>For preview use the <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/packages/views/src/knowledge/markdown-content.tsx" target="_blank" rel="noreferrer">safe rendering reference</a>: <code>react-markdown / remark-gfm / rehype-sanitize</code>, no raw HTML and preserved URL protocol filtering. The server does not fetch external links and external images do not load automatically. Attachments use <a href="./attachments">authorized references</a>, never stored signed URLs.</p><p>Load preview on demand, separate drafts from saved resources and preserve input when rejecting over-budget preview/submission. Rendering does not replace backend authorization. Your search rules may differ, but change DTO, SQL, cursor and checks together. Continue with <a href="./edit-conflicts">versioned updates</a>.</p><hr><p>Source version：<code>261be5bb90df</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/docs/tutorials/05-search-preview.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,19)])])}const u=a(n,[["render",r]]);export{k as __pageData,u as default};
